arguments.command:
cd /workspace && OPENBLAS_NUM_THREADS=1 LD_LIBRARY_PATH=/workspace/native PYTHONPATH=/workspace/.deps:/workspace/submission python3 - <<'EOF'
import sys, copy, traceback
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tests')
from protocol import validate, InvalidRequest
import importlib.util
spec=importlib.util.spec_from_file_location("tv","/workspace/tests/test_validation.py")
# just read BASE by exec of the top part
src=open('/workspace/tests/test_validation.py').read()
ns={}
exec(src.split('def req(')[0], ns)
BASE=ns['BASE']
print(BASE)
for n,cases in [("6 cases",[copy.deepcopy(BASE) for _ in range(6)]),
                ("48 issues",None),
                ("256 events",None)]:
    if cases is None:
        d={"cases":[copy.deepcopy(BASE)]}
        if n=="48 issues":
            d["cases"][0]["events"]=[{"op":"issue","id":i,"worker":0} for i in range(48)]
        else:
            d["cases"][0]["events"]=[{"op":"step"}]*256
    else:
        d={"cases":cases}
    try:
        validate(d); print(n,"accepted")
    except InvalidRequest:
        import pdb; traceback.print_exc(limit=3)
EOF
